"use client"

import type { KeyboardEvent } from "react"
import { SearchIcon } from "lucide-react"

import { useFilterScope } from "@/components/ui/filter-scope"
import { Input, InputGroup } from "@/components/ui/input"
import { searchFieldOf, type FilterSchema, type FilterValues } from "@/lib/filter-schema"
import type { PageController } from "@/lib/page-controller"
import { cn } from "@/lib/utils"

type FilterSearchProps<S extends FilterSchema> = {
  /** Defaults to the schema's first text field's label. */
  label?: string
  placeholder?: string
  schema?: S
  controller?: PageController<FilterValues<S>>
  className?: string
}

/**
 * The schema's search field: shows the text at once and commits it after the controller's debounce (250 ms).
 * Enter commits at once, Escape clears. An agent's value commits without waiting.
 */
function FilterSearch<S extends FilterSchema>({ label, placeholder, className, ...props }: FilterSearchProps<S>) {
  const { schema, controller, state, searchPlaceholder } = useFilterScope(props)
  const key = searchFieldOf(schema)
  const name = label ?? (key === undefined ? undefined : schema[key]?.label) ?? ""
  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Enter" && !event.nativeEvent.isComposing) {
      event.preventDefault()
      controller.flushSearch()
    } else if (event.key === "Escape" && state.searchText !== "") {
      event.preventDefault()
      event.stopPropagation()
      controller.setSearch("", { immediate: true })
    }
  }
  return (
    <InputGroup
      render={<search />}
      aria-label={name}
      data-slot="filter-search"
      className={cn("w-full sm:max-w-72 sm:flex-1", className)}
    >
      <SearchIcon />
      <Input
        type="search"
        aria-label={name}
        placeholder={placeholder ?? searchPlaceholder}
        value={state.searchText}
        onValueChange={(value, details) =>
          controller.setSearch(value, { immediate: (details as { source?: string } | undefined)?.source === "agent" })
        }
        onKeyDown={onKeyDown}
        className="[&::-webkit-search-cancel-button]:hidden"
      />
    </InputGroup>
  )
}

export { FilterSearch }
export type { FilterSearchProps }

"use client"

import { usePart, usePrimitive } from "@ui-sdk/react/primitive"
import { createContext, use, useMemo, useSyncExternalStore, type ReactNode } from "react"

import { serverFilters } from "@/components/ui/server-filters-primitive"
import { findFilterKey, parseFilterInput } from "@/lib/filter-input"
import { searchFieldOf, type FilterSchema, type FilterValues } from "@/lib/filter-schema"
import type { PageController } from "@/lib/page-controller"

type AnyController = PageController<FilterValues<FilterSchema>>

type FilterScopeValue = { schema: FilterSchema; controller: AnyController; searchPlaceholder?: string }

const FilterScopeContext = createContext<FilterScopeValue | null>(null)

type FilterScopeProps<S extends FilterSchema> = {
  schema: S
  controller: PageController<FilterValues<S>>
  /** Names the filters for agents, who set them with `filter(field, value)`, `search` and `clearFilters`. */
  label: string
  /** The placeholder of a `FilterSearch` inside that doesn't set its own: "Search tasks…". */
  searchPlaceholder?: string
  className?: string
  children?: ReactNode
}

/**
 * Gives filter UIs inside it (`FilterSearch`, `FilterChips`, `FilterPanel`) their schema and controller, and lets
 * agents filter by a field's label: `filter("Status", ["Open", "Blocked"])`.
 */
function FilterScope<S extends FilterSchema>({
  schema,
  controller,
  label,
  searchPlaceholder,
  className,
  children,
}: FilterScopeProps<S>) {
  const scope = useMemo(
    () => ({ schema, controller: controller as unknown as AnyController, searchPlaceholder }),
    [schema, controller, searchPlaceholder],
  )
  const handle = usePrimitive(serverFilters, {
    fields: Object.entries(schema).map(([key, field]) => ({ value: key, label: field.label })),
    apply: (name, input) => {
      const key = findFilterKey(schema, name)
      const field = schema[key] as S[keyof S]
      const value = parseFilterInput(field, input)
      if (key === searchFieldOf(schema))
        controller.setSearch(typeof value === "string" ? value : "", { immediate: true })
      else controller.setFilterValue(key, value as FilterValues<S>[typeof key])
    },
    clear: () => controller.resetFilters(),
  })
  return usePart(
    handle,
    "root",
    {},
    {
      "aria-label": label,
      className,
      children: <FilterScopeContext value={scope}>{children}</FilterScopeContext>,
    },
    "div",
  )
}

/** The schema and controller of the nearest `FilterScope`, or the ones passed; and the controller's state. */
function useFilterScope<S extends FilterSchema>(props: { schema?: S; controller?: PageController<FilterValues<S>> }) {
  const scope = use(FilterScopeContext)
  const schema = (props.schema ?? scope?.schema) as S | undefined
  const controller = (props.controller ?? scope?.controller) as PageController<FilterValues<S>> | undefined
  if (!schema || !controller)
    throw new Error("A filter UI needs `schema` and `controller`, or a FilterScope around it.")
  const state = useSyncExternalStore(controller.subscribe, controller.getState, controller.getState)
  return { schema, controller, state, searchPlaceholder: scope?.searchPlaceholder }
}

export { FilterScope, useFilterScope }
export type { FilterScopeProps }

import { definePrimitive } from "@ui-sdk/core"

type ServerFiltersField = { value: string; label: string }

type ServerFiltersOptions = {
  /** The schema's fields, by key and label: what `filter` takes as its first argument. */
  fields?: readonly ServerFiltersField[]
  /** Sets one field from loose input; throws a `RangeError` that says what the field takes. */
  apply?: (field: unknown, value: unknown) => void
  clear?: () => void
}

// The agent bridge passes arguments unchecked; `apply` validates the field and the value against the schema.
const serverFilters = definePrimitive({
  name: "server-filters",
  options: { fields: "list", apply: "value", clear: "value" },
  state: (options: ServerFiltersOptions) => ({ count: options.fields?.length ?? 0 }),
  sync: (options) => ({ count: options.fields?.length ?? 0 }),
  api: (context) => ({
    filter(field: unknown, value?: unknown) {
      const apply = context.options().apply
      if (!apply) return false
      apply(field, value)
      return true
    },
    clearFilters() {
      context.options().clear?.()
      return true
    },
    fields: () => context.options().fields ?? [],
  }),
  slots: (slot) => ({
    root: slot({ role: "group", attrs: (state) => ({ "data-count": String(state.count) }) }),
  }),
  agent: { actions: ["filter", "clearFilters"], items: (api) => api.fields() },
})

export { serverFilters }
export type { ServerFiltersField, ServerFiltersOptions }
